#!/usr/bin/env python3
"""Royal Void 0.3 owner tool. Never include this file or signing key in an APK."""
import argparse, base64, getpass, hashlib, importlib.util, json, os, tempfile, time, urllib.request, urllib.error, zlib
from pathlib import Path
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

PUBLIC_KEY = "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEBvmVi6bDPa9eUOBNsYKr+IQ3JW3rQPQpeWxhi/fTTuLIn8jtG3vDb1G2y9286BKW1GKs2zksU9Grw6eFMHF7Aw=="
WORKER = "https://dg.dynamongamer30.workers.dev"
OWNER_DATA = ""

def b64(value):
    return base64.b64encode(value).decode("ascii")

def prepare(original, config_dir=None):
    files = json.loads(zlib.decompress(base64.b64decode(OWNER_DATA)))
    if config_dir is not None:
        for name in ("brand.json", "menu_config.json", "catalog.json", "patches.json"):
            path = config_dir / name
            if path.exists():
                data = json.loads(path.read_text())
                files["integration/" + name] = json.dumps(data)

    with tempfile.TemporaryDirectory(prefix="rv-owner-") as directory:
        module_path = Path(directory) / "patch_engine.py"
        module_path.write_text(files["integration/patch_dynamons.py"])
        spec = importlib.util.spec_from_file_location("rv_patch_engine", module_path)
        engine = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(engine)
        source = original.decode("utf-8")
        edits = []
        for rule in json.loads(files["integration/patches.json"])["rules"]:
            status, match, _ = engine.locate(source, rule)
            if status != "ok":
                raise ValueError("Patch rule %s could not be applied unambiguously (%s). Nothing uploaded." % (rule["id"], match))
            edits.append((match.start(), match.end(), engine.apply_segs(match, rule["repl_segs"]), rule["id"]))
        edits.sort()
        for previous, current in zip(edits, edits[1:]):
            if current[0] < previous[1]:
                raise ValueError("Overlapping patches. Nothing uploaded.")
        for start, end, replacement, _ in reversed(edits):
            source = source[:start] + replacement + source[end:]
    source += "\n;\n"
    for variable, filename in [("__DG_BRAND","brand.json"),("__DG_MENU_CONFIG","menu_config.json"),("__DG_CATALOG","catalog.json")]:
        source += "window." + variable + "=" + json.dumps(json.loads(files["integration/" + filename]), ensure_ascii=True) + ";\n"
    source += files["tests/bootstrap.js"] + "\n"
    return source.encode("utf-8"), len(edits)

def load_key(path):
    key = serialization.load_pem_private_key(path.read_bytes(), password=None)
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(key.curve, ec.SECP256R1):
        raise ValueError("Signing key must be ECDSA P-256.")
    public = key.public_key().public_bytes(serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo)
    if b64(public) != PUBLIC_KEY:
        raise ValueError("Signing key does not match the key pinned in Royal Void 0.3 DEX. Nothing uploaded. Do not generate a replacement key.")
    return key

def sign(key, message):
    r, s = decode_dss_signature(key.sign(message, ec.ECDSA(hashes.SHA256())))
    return b64(r.to_bytes(32, "big") + s.to_bytes(32, "big"))

def seal(payload, key, build):
    aes_key, iv = os.urandom(32), os.urandom(12)
    ciphertext = AESGCM(aes_key).encrypt(iv, payload, None)
    digest = hashlib.sha256(ciphertext).hexdigest()
    issued = int(time.time())
    message = ("DG-PAYLOAD-V2\n%s\n%s\n%s\n%s\n3" % (build, digest, b64(iv), issued)).encode()
    return dict(build=build, protocol=2, min_client=3, issued=issued,
                ct_b64=b64(ciphertext), iv_b64=b64(iv), ct_sha=digest,
                sig_b64=sign(key, ciphertext), meta_sig_b64=sign(key, message), key_b64=b64(aes_key))

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def upload(bundle, admin_key):
    request = urllib.request.Request(WORKER + "/admin/upload-payload",
        data=json.dumps(bundle).encode("utf-8"), method="POST",
        headers={"Content-Type":"application/json", "X-Admin":admin_key,
                 "Accept":"application/json",
                 "User-Agent":"Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Mobile Safari/537.36"})
    try:
        with urllib.request.build_opener(NoRedirect()).open(request, timeout=30) as response:
            result = json.loads(response.read(65536))
    except urllib.error.HTTPError as error:
        raw = error.read(4096).decode("utf-8", errors="replace")
        if admin_key:
            raw = raw.replace(admin_key, "[REDACTED]")
        try:
            detail = json.loads(raw)
            description = str(detail.get("error", detail.get("message", "JSON error"))) if isinstance(detail, dict) else "JSON error"
        except (ValueError, TypeError):
            description = "Non-JSON response: " + " ".join(raw.split())[:500]
        if admin_key:
            description = description.replace(admin_key, "[REDACTED]")
        ray = error.headers.get("CF-Ray", "not provided")
        raise ValueError("Upload failed: HTTP %s; response: %s; CF-Ray: %s. Worker: %s" % (error.code, description, ray, WORKER)) from None
    except (urllib.error.URLError, TimeoutError) as error:
        raise ValueError("Upload connection failed. The server may have received the request; check current_build before retrying.") from None
    if result.get("ok") is not True or result.get("build") != bundle["build"]:
        raise ValueError("Worker did not confirm the upload. Check its deployment and bindings.")

def main():
    parser = argparse.ArgumentParser(description="Prepare, encrypt, sign and upload the Royal Void 0.3 game payload.")
    parser.add_argument("--original", type=Path, required=True, help="Unmodified matching game dynamons_world.min.js")
    parser.add_argument("--signing-key", type=Path, required=True, help="Existing signing_key.pem; never upload it anywhere")
    parser.add_argument("--config-dir", type=Path, help="Optional owner directory with branding, catalogue or patch overrides")
    parser.add_argument("--bundle-out", type=Path, help="Export a private encrypted upload bundle for the admin panel; do not upload now")
    args = parser.parse_args()
    try:
        key = load_key(args.signing_key)
        payload, count = prepare(args.original.read_bytes(), args.config_dir)
        build = "royalvoid-03-" + time.strftime("%Y%m%d-%H%M%S", time.gmtime()) + "-" + os.urandom(3).hex()
        bundle = seal(payload, key, build)
        if len(bundle["ct_b64"]) > 10000000:
            raise ValueError("Payload exceeds this Worker's configured size limit. Nothing uploaded.")
        print("Prepared %d patches and native menu runtime." % count)
        print("Build: " + build)
        if args.bundle_out:
            with os.fdopen(os.open(args.bundle_out, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), "w") as file:
                json.dump(bundle, file)
            print("Exported private upload bundle: " + str(args.bundle_out))
            print("Contains the AES key. Upload only through your owner admin panel; never publish or bundle in APK.")
            return
        print("Uploading publishes this build for clients using the current payload.")
        admin = os.environ.get("DG_ADMIN_KEY") or getpass.getpass("Cloudflare ADMIN_KEY (hidden): ")
        if not admin:
            raise ValueError("ADMIN_KEY is empty. Nothing uploaded.")
        upload(bundle, admin)
        print("SUCCESS: encrypted payload uploaded and set as current.")
        print("Fully close and reopen the game, complete login, then check GAME CONNECTED.")
    except (ValueError, OSError) as error:
        parser.exit(1, "STOP: " + str(error) + "\n")

if __name__ == "__main__":
    main()
